def _rand_bytes(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    return bytes(rng.getrandbits(8) for _ in range(n))

def _numeric_only(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    return bytes(rng.choice(b"0123456789") for _ in range(n))

def _alnum_qr(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    return bytes(rng.choice(ALNUM_QR_SET) for _ in range(n))

def _utf8_text(rng: random.Random, min_len: int, max_len: int) -> bytes:
    if max_len < 1:
        return b""
    if min_len < 1:
        min_len = 1
    if min_len > max_len:
        min_len = max_len
    length = rng.randint(min_len, max_len)
    out = bytearray()
    while len(out) < length:
        choice = rng.random()
        if choice < 0.5:
            out.append(rng.randrange(0x20, 0x7F))  # ASCII
        elif choice < 0.75:
            cp = rng.randrange(0x00A0, 0x07FF)
            out.extend(chr(cp).encode('utf-8'))
        elif choice < 0.95:
            cp = rng.randrange(0x0800, 0xFFFF)
            if 0xD800 <= cp <= 0xDFFF:
                cp = 0xFFFD
            out.extend(chr(cp).encode('utf-8'))
        else:
            cp = rng.randrange(0x10000, 0x10FFFF)
            out.extend(chr(cp).encode('utf-8'))
    return bytes(out[:length])

def _structured_url(rng: random.Random) -> bytes:
    scheme = rng.choice(URL_SCHEMES)
    host = rng.choice(COMMON_HOSTS)
    path = rng.choice(PATHS)
    qf = rng.choice(QUERY_FRAG + [b"", b""])
    return scheme + host + path + qf

def _mailto(rng: random.Random) -> bytes:
    return b"mailto:" + rng.choice(EMAILS)

def _wifi(rng: random.Random) -> bytes:
    return rng.choice(WIFI_TEMPLATES)

def _vcard(rng: random.Random) -> bytes:
    return rng.choice(VCARD_SAMPLES)

def _geo(rng: random.Random) -> bytes:
    lat = (rng.random()*180) - 90
    lon = (rng.random()*360) - 180
    prec = rng.randint(0, 8)
    return f"geo:{lat:.6f},{lon:.6f};u={prec}".encode()

def _with_checksum(prefix: bytes, payload: bytes) -> bytes:
    crc = zlib.crc32(payload) & 0xFFFFFFFF
    return prefix + payload + struct.pack('>I', crc)

VARIANTS = [
    "numeric", "alnum", "utf8", "random", "repetitions",
    "url", "mailto", "wifi", "vcard", "geo", "checksum_bin"
]

def _safe_randint(rng: random.Random, a: int, b: int) -> int:
    if b < a:
        b = a
    return rng.randint(a, b)

def _make_payload(rng: random.Random) -> bytes:
    variant = rng.choice(VARIANTS)

    # Choose target length biased towards boundaries
    if rng.random() < 0.6:
        base_len = rng.choice(BOUNDARY_LENGTHS)
        jitter = rng.randint(-8, 16)
        tgt = max(1, min(MAX_LEN, base_len + jitter))
    else:
        tgt = rng.randint(1, min(1500, MAX_LEN))

    if variant == "numeric":
        return _numeric_only(rng, tgt)
    if variant == "alnum":
        return _alnum_qr(rng, tgt)
    if variant == "utf8":
        return _utf8_text(rng, max(1, tgt//2), tgt)
    if variant == "random":
        return _rand_bytes(rng, tgt)
    if variant == "repetitions":
        # Create runs; guard against zero remaining space for randint
        chunks = []
        produced = 0
        while produced < tgt:
            remaining = tgt - produced
            # run of repeated byte
            b = rng.randrange(0, 256)
            run = _safe_randint(rng, 1, min(256, remaining))
            chunks.append(bytes([b]) * run)
            produced += run
            remaining = tgt - produced
            if remaining <= 0:
                break
            # optional random spurts
            if rng.random() < 0.4:
                spur_len = _safe_randint(rng, 1, min(32, remaining))
                chunks.append(_rand_bytes(rng, spur_len))
                produced += spur_len
        return b"".join(chunks)[:tgt]
    if variant == "url":
        p = _structured_url(rng)
        if rng.random() < 0.5:
            tail_len = _safe_randint(rng, 6, 24)
            p += b"&token=" + _alnum_qr(rng, tail_len)
        return p[:tgt]
    if variant == "mailto":
        p = _mailto(rng)
        if rng.random() < 0.5:
            subj_len = _safe_randint(rng, 4, 16)
            p += b"?subject=" + _alnum_qr(rng, subj_len)
        return p[:tgt]
    if variant == "wifi":
        return _wifi(rng)[:tgt]
    if variant == "vcard":
        return _vcard(rng)[:tgt]
    if variant == "geo":
        return _geo(rng)[:tgt]
    if variant == "checksum_bin":
        core_len = max(1, tgt - 6)
        core = _rand_bytes(rng, core_len)
        return _with_checksum(b"BIN:\x00", core)[:tgt]
    return _rand_bytes(rng, tgt)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    parts = []
    count = 1 if rng.random() < 0.6 else rng.randint(2, 4)
    for _ in range(count):
        part = _make_payload(rng)
        parts.append(part)
        if rng.random() < 0.5:
            parts.append(rng.choice([b"\n", b"\r\n", b" ", b"||", b"\t"]))
    data = b"".join(parts)
    if len(data) > MAX_LEN:
        data = data[:MAX_LEN]
    if not data:
        data = b"0"
    return data
